parameters.jsCode:
// ✏️ Nguồn RSS cho TikTok — chủ đề vegan & quyền động vật, tin tiếng Anh + tiếng Việt.
//   lang    = ngôn ngữ của nguồn (en / vi). Mỗi bài luôn tạo 2 bản: tiếng Anh + tiếng Việt.
//   count   = số bài tối đa lấy từ chủ đề này mỗi lần chạy (chủ đề khác thiếu bài thì chủ đề này lấy bù).
//   include = regex (tuỳ chọn); bài phải khớp (tiêu đề + tóm tắt) mới được lấy — dùng cho báo tổng hợp.
//   colors  = màu nền dự phòng khi bài không có ảnh nào.
const EN_ANIMAL = 'vegan|plant-based|animal|sanctuary|wildlife|rescue';
const VI_ANIMAL = 'động vật|thú cưng|thịt chó|thịt mèo|\\bvoi\\b|\\bhổ\\b|\\bgấu\\b|tê tê|\\bkhỉ\\b|cá heo|\\brùa\\b|hoang dã|cứu hộ|nuôi nhốt|ngược đãi|giết mổ|lò mổ|thuần chay|ăn chay|món chay|đồ chay|sách đỏ|quý hiếm|ngà voi|sừng tê|mật gấu|buôn lậu động vật|thả về tự nhiên';

const TOPICS = [
  {
    id: 'vegan', lang: 'en', count: 5,
    label: 'Vegan',
    guide: 'Vegan lifestyle and plant-based news: warm, hopeful, practical.',
    colors: ['#14532d', '#16a34a'],
    feeds: [
      { url: 'https://plantbasednews.org/feed/' },
      { url: 'https://www.veganfoodandliving.com/feed/' },
      { url: 'https://www.theguardian.com/lifeandstyle/veganism/rss' },
    ],
  },
  {
    id: 'animal-rights', lang: 'en', count: 5,
    label: 'Animal rights',
    guide: 'Animal-rights and animal-welfare news: honest but never graphic, compassionate, end with a constructive action.',
    colors: ['#7f1d1d', '#dc2626'],
    feeds: [
      { url: 'https://sentientmedia.org/feed/' },
      { url: 'https://mercyforanimals.org/feed/' },
      { url: 'https://www.farmsanctuary.org/feed/' },
      { url: 'https://animalequality.org/feed/' },
      { url: 'https://www.goodnewsnetwork.org/feed/', include: EN_ANIMAL },
    ],
  },
  {
    id: 'dong-vat-vn', lang: 'vi', count: 4,
    label: 'Động vật & ăn chay (tin Việt Nam)',
    guide: 'Tin về bảo vệ động vật, động vật hoang dã, cứu hộ, ăn chay: nhẹ nhàng, nhân ái, không giật gân, không mô tả cảnh máu me.',
    colors: ['#134e4a', '#14b8a6'],
    feeds: [
      { url: 'https://vnexpress.net/rss/thoi-su.rss', include: VI_ANIMAL },
      { url: 'https://vnexpress.net/rss/the-gioi.rss', include: VI_ANIMAL },
      { url: 'https://vnexpress.net/rss/khoa-hoc.rss', include: VI_ANIMAL },
      { url: 'https://dantri.com.vn/rss/khoa-hoc.rss', include: VI_ANIMAL },
      { url: 'https://dantri.com.vn/rss/home.rss', include: VI_ANIMAL },
      { url: 'https://tuoitre.vn/rss/tin-moi-nhat.rss', include: VI_ANIMAL },
      { url: 'https://thanhnien.vn/rss/home.rss', include: VI_ANIMAL },
    ],
  },
];

return TOPICS.flatMap((t) =>
  t.feeds.map((f) => ({
    json: { topic: t.id, label: t.label, guide: t.guide, colors: t.colors, lang: t.lang, count: t.count, url: f.url, include: f.include || '' },
  })),
);

// Đọc tất cả feed song song, chọn bài MỚI NHẤT chưa đăng của mỗi chủ đề (xen kẽ chủ đề),
// rồi mở trang bài để lấy nội dung + NHIỀU ảnh (mỗi slide TikTok một ảnh).
const cfg = $('Config').first().json;
const feeds = $input.all().map((i) => i.json);
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';
const MAX_AGE_MS = Number(cfg.maxAgeDays || 14) * 86400000;
const MAX_POSTS = Number(cfg.maxArticles || 4);
// chọn dư ứng viên: Gemini sẽ loại bài lạc đề, giữ đủ maxArticles bài đạt
const MAX_CANDIDATES = Math.ceil(MAX_POSTS * Number(cfg.candidateFactor || 1.5));
const MAX_IMAGES = Number(cfg.maxImagesPerPost || 6);
const now = Date.now();

let seen = {};
try { seen = $getWorkflowStaticData('global').seenTikTok || {}; } catch (e) { /* static data unavailable */ }

// ---------- helpers ----------
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', rsquo: '’', lsquo: '‘', ldquo: '“', rdquo: '”', hellip: '…', ndash: '–', mdash: '—' };
const decode = (s) =>
  String(s || '').replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const c = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      try { return String.fromCodePoint(c); } catch (x) { return m; }
    }
    return ENT[e.toLowerCase()] ?? m;
  });
const stripHtml = (h) =>
  decode(String(h || '').replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const inner = (block, name) => {
  const m = block.match(new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + name + '>', 'i'));
  if (!m) return '';
  const v = m[1].trim();
  const cd = v.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
  return cd ? cd[1].trim() : decode(v);
};
const attrs = (s) => {
  const o = {};
  for (const m of s.matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g)) o[m[1].toLowerCase()] = decode(m[2] ?? m[3]);
  return o;
};
// (sandbox của Code node không có global URL nên tự xử lý chuỗi)
const hostOf = (u) => { const m = String(u).match(/^https?:\/\/([^/?#:]+)/i); return m ? m[1].replace(/^www\./i, '') : ''; };
const absUrl = (u, base) => {
  u = String(u || '').trim();
  if (/^https?:\/\//i.test(u)) return u;
  const b = String(base || '');
  const origin = (b.match(/^(https?:\/\/[^/?#]+)/i) || [])[1];
  if (!origin) return '';
  if (u.startsWith('//')) return 'https:' + u;
  if (u.startsWith('/')) return origin + u;
  return b.replace(/[?#].*$/, '').replace(/[^/]*$/, '') + u;
};
const BAD_IMG = /(gravatar|pixel|tracking|spacer|blank\.|emoji|1x1|\.gif(\?|$)|\.svg(\?|$)|\/logo|avatar|badge|favicon|doubleclick|feedburner)/i;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const toBuf = (b) => {
  if (Buffer.isBuffer(b)) return b;
  if (b && b.type === 'Buffer' && Array.isArray(b.data)) return Buffer.from(b.data);
  if (b instanceof ArrayBuffer) return Buffer.from(b);
  if (b && b.buffer instanceof ArrayBuffer) return Buffer.from(b.buffer, b.byteOffset, b.byteLength);
  return null;
};
const sniff = (b) => {
  if (!b || b.length < 12) return null;
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'image/jpeg';
  if (b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) return 'image/png';
  if (b.toString('latin1', 0, 4) === 'RIFF' && b.toString('latin1', 8, 12) === 'WEBP') return 'image/webp';
  return null;
};
const normKey = (link) => {
  const [path, query = ''] = String(link).replace(/#.*$/, '').replace(/^https?:\/\/(www\.)?/i, '').split('?');
  const q = query.split('&').filter((p) => p && !/^(utm_|fbclid|ref=|source=|at_)/i.test(p)).join('&');
  return (path.replace(/\/+$/, '') + (q ? '?' + q : '')).toLowerCase();
};
const titleKey = (t) => String(t).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

// ---------- parse one feed ----------
function parseFeed(xml, feed) {
  const out = [];
  for (const m of xml.matchAll(/<(item|entry)[\s>][\s\S]*?<\/\1>/gi)) {
    const block = m[0];
    const title = stripHtml(inner(block, 'title'));
    let link = stripHtml(inner(block, 'link'));
    if (!link) {
      const links = [...block.matchAll(/<link\b([^>]*)\/?>/gi)].map((x) => attrs(x[1]));
      const alt = links.find((l) => l.href && (!l.rel || l.rel === 'alternate')) || links.find((l) => l.href);
      link = alt ? alt.href : '';
    }
    if (!link) { const g = inner(block, 'guid'); if (/^https?:/i.test(g)) link = g; }
    if (!title || !/^https?:/i.test(link)) continue;
    const dateStr = inner(block, 'pubDate') || inner(block, 'published') || inner(block, 'updated') || inner(block, 'dc:date');
    const date = Date.parse(dateStr);
    const htmlBody = inner(block, 'content:encoded') || inner(block, 'content') || inner(block, 'description') || inner(block, 'summary');
    const descr = stripHtml(inner(block, 'description') || inner(block, 'summary'));
    const full = stripHtml(htmlBody);
    const summary = (full.length > descr.length ? full : descr).slice(0, 2200);

    // image candidates: media:content / thumbnail / enclosure, then <img> inside the body
    const media = [];
    for (const t of block.matchAll(/<(media:content|media:thumbnail|enclosure|itunes:image)\b([^>]*)>/gi)) {
      const a = attrs(t[2]);
      const u = a.url || a.href;
      if (!u) continue;
      const kind = (a.type || a.medium || '').toLowerCase();
      const isImg = kind.startsWith('image') || (!kind && /\.(jpe?g|png|webp)(\?|$)/i.test(u)) || /thumbnail|itunes:image/i.test(t[1]);
      if (!isImg || BAD_IMG.test(u)) continue;
      media.push({ u: absUrl(u, link), w: Number(a.width) || 0 });
    }
    media.sort((x, y) => y.w - x.w);
    const inline = [];
    for (const t of htmlBody.matchAll(/<img\b([^>]*)>/gi)) {
      const a = attrs(t[1]);
      let u = a['data-src'] || a['data-lazy-src'] || a['data-orig-file'] || '';
      if (!u && a.srcset) u = a.srcset.split(',').pop().trim().split(/\s+/)[0];
      if (!u) u = a.src || '';
      if (!u || /^data:/i.test(u) || BAD_IMG.test(u)) continue;
      if (Number(a.width) && Number(a.width) < 200) continue;
      inline.push(absUrl(u, link));
    }
    const images = [...new Set([...media.map((x) => x.u), ...inline].filter(Boolean))].slice(0, 4);

    out.push({
      topic: feed.topic, label: feed.label, guide: feed.guide, colors: feed.colors, lang: feed.lang, count: feed.count,
      title, link, date, summary, images,
      source: hostOf(link),
    });
  }
  return out;
}

// ---------- 1) fetch all feeds in parallel ----------
const feedErrors = [];
const fetched = await Promise.all(
  feeds.map(async (f) => {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', url: f.url, timeout: 25000, encoding: 'text', returnFullResponse: true, ignoreHttpStatusErrors: true,
        headers: { 'User-Agent': UA, Accept: 'application/rss+xml, application/atom+xml, application/xml, text/xml, */*' },
      });
      if (res.statusCode >= 400) throw new Error('HTTP ' + res.statusCode);
      let items = parseFeed(String(res.body), f);
      if (f.include) { const re = new RegExp(f.include, 'i'); items = items.filter((a) => re.test(a.title + ' ' + a.summary)); }
      return items;
    } catch (e) {
      feedErrors.push(f.url + ' → ' + String(e.message).slice(0, 80));
      return [];
    }
  }),
);
if (!fetched.some((x) => x.length) && feedErrors.length === feeds.length) {
  throw new Error('Không đọc được feed nào (kiểm tra mạng của container). Ví dụ: ' + feedErrors.slice(0, 3).join(' | '));
}


// ---------- 2) pick: xen kẽ từng vòng giữa các chủ đề, mỗi chủ đề tối đa `count` bài ----------
const byTopic = new Map();
for (const f of feeds) if (!byTopic.has(f.topic)) byTopic.set(f.topic, { count: Number(f.count) || 1, items: [] });
fetched.flat().forEach((a) => byTopic.get(a.topic).items.push(a));
const topicIds = [...byTopic.keys()];
const rot = Math.floor(now / 86400000) % topicIds.length;
const order = [...topicIds.slice(rot), ...topicIds.slice(0, rot)];
const usedKeys = new Set();
const usedTitles = new Set();
const picks = [];
// mỗi vòng lấy 1 bài / chủ đề; chủ đề hết bài thì chủ đề khác lấy bù (tối đa `count` bài / chủ đề)
const maxRounds = Math.max(...[...byTopic.values()].map((t) => t.count));
for (let round = 0; round < maxRounds && picks.length < MAX_CANDIDATES; round++) {
  for (const topic of order) {
    if (picks.length >= MAX_CANDIDATES) break;
    const t = byTopic.get(topic);
    if (round >= t.count) continue;
    const a = t.items
      .filter((x) => x.date && x.date <= now + 86400000 && now - x.date <= MAX_AGE_MS)
      .filter((x) => !seen[normKey(x.link)] && !usedKeys.has(normKey(x.link)) && !usedTitles.has(titleKey(x.title)))
      .sort((x, y) => y.date - x.date)[0];
    if (!a) continue;
    usedKeys.add(normKey(a.link));
    usedTitles.add(titleKey(a.title));
    picks.push(a);
  }
}
const chosen = picks.slice(0, MAX_CANDIDATES);

// ---------- 3) mở trang bài: lấy nội dung + tải nhiều ảnh ----------
const started = Date.now();
const DEADLINE = Number(cfg.fetchDeadlineSec || 600) * 1000; // Code node bị ngắt sau N8N_RUNNERS_TASK_TIMEOUT → dừng tìm thêm ảnh khi gần hết giờ
const imageSize = (b) => {
  try {
    if (b[0] === 0x89 && b[1] === 0x50) return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) };
    if (b[0] === 0xff && b[1] === 0xd8) {
      let o = 2;
      while (o < b.length - 9) {
        if (b[o] !== 0xff) { o++; continue; }
        const m = b[o + 1];
        if (m === 0xd8 || m === 0x01 || (m >= 0xd0 && m <= 0xd7) || m === 0xff) { o += m === 0xff ? 1 : 2; continue; }
        if (m >= 0xc0 && m <= 0xcf && m !== 0xc4 && m !== 0xc8 && m !== 0xcc) return { h: b.readUInt16BE(o + 5), w: b.readUInt16BE(o + 7) };
        o += 2 + b.readUInt16BE(o + 2);
      }
    }
    if (b.toString('latin1', 0, 4) === 'RIFF') {
      const t = b.toString('latin1', 12, 16);
      if (t === 'VP8 ') return { w: b.readUInt16LE(26) & 0x3fff, h: b.readUInt16LE(28) & 0x3fff };
      if (t === 'VP8L') { const v = b.readUInt32LE(21); return { w: (v & 0x3fff) + 1, h: ((v >> 14) & 0x3fff) + 1 }; }
      if (t === 'VP8X') return { w: 1 + b.readUIntLE(24, 3), h: 1 + b.readUIntLE(27, 3) };
    }
  } catch (e) { /* ignore */ }
  return null;
};
const download = async (url, referer) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url, timeout: 15000, encoding: 'arraybuffer', returnFullResponse: true, ignoreHttpStatusErrors: true,
      headers: { 'User-Agent': UA, Accept: 'image/webp,image/png,image/jpeg,*/*;q=0.8', Referer: referer },
    });
    if (res.statusCode >= 400) return null;
    const buf = toBuf(res.body);
    const mime = sniff(buf);
    if (!mime || buf.length < 12000 || buf.length > 9 * 1024 * 1024) return null;
    const size = imageSize(buf);
    if (!size) return null;
    return { buf, mime, w: size.w, h: size.h };
  } catch (e) { return null; }
};
const fetchPage = async (page) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: page, timeout: 15000, encoding: 'text', returnFullResponse: true, ignoreHttpStatusErrors: true,
      headers: { 'User-Agent': UA, Accept: 'text/html,*/*' },
    });
    return res.statusCode >= 400 ? '' : String(res.body).slice(0, 1500000);
  } catch (e) { return ''; }
};
// phần thân bài: <article> nếu có, không thì từ thẻ <h1> trở đi (tránh ảnh menu / logo đầu trang)
const mainPart = (html) => {
  const m = html.match(/<article\b[\s\S]*?<\/article>/i);
  if (m && m[0].length > 2000) return m[0];
  const h1 = html.search(/<h1\b/i);
  return h1 >= 0 ? html.slice(h1, h1 + 250000) : html;
};
const pageImages = (html, page) => {
  const out = [];
  for (const t of html.matchAll(/<meta\b([^>]*)>/gi)) {
    const a = attrs(t[1]);
    const k = (a.property || a.name || '').toLowerCase();
    if ((k === 'og:image' || k === 'og:image:url' || k === 'twitter:image') && a.content) { out.push(absUrl(a.content, page)); break; }
  }
  for (const t of mainPart(html).matchAll(/<img\b([^>]*)>/gi)) {
    const a = attrs(t[1]);
    let u = a['data-src'] || a['data-original'] || a['data-lazy-src'] || a['data-orig-file'] || '';
    if (!u && (a['data-srcset'] || a.srcset)) u = (a['data-srcset'] || a.srcset).split(',').pop().trim().split(/\s+/)[0];
    if (!u) u = a.src || '';
    if (!u || /^data:/i.test(u) || BAD_IMG.test(u)) continue;
    if (Number(a.width) && Number(a.width) < 300) continue;
    out.push(absUrl(u, page));
  }
  return out;
};
// JSON-LD (schema.org NewsArticle) — nhiều báo nhúng sẵn danh sách ảnh + nội dung bài, kể cả trang dựng bằng JavaScript
const ldJson = (html, page) => {
  const res = { images: [], body: '' };
  const walk = (v) => {
    if (Array.isArray(v)) return v.forEach(walk);
    if (!v || typeof v !== 'object') return;
    if (/Article|Posting/i.test(String(v['@type'] || ''))) {
      const im = v.image;
      for (const x of Array.isArray(im) ? im : [im]) {
        const u = typeof x === 'string' ? x : x && (x.url || x.contentUrl);
        if (u) res.images.push(absUrl(u, page));
      }
      if (typeof v.articleBody === 'string' && v.articleBody.length > res.body.length) res.body = stripHtml(v.articleBody);
    }
    Object.values(v).forEach((x) => typeof x === 'object' && walk(x));
  };
  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    try { walk(JSON.parse(m[1].trim())); } catch (e) { /* JSON-LD lỗi → bỏ qua */ }
  }
  return res;
};
const pageText = (html) => {
  const ps = [...mainPart(html).matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)].map((m) => stripHtml(m[1])).filter((p) => p.length > 60);
  return ps.join('\n').slice(0, 6000);
};
// cùng một ảnh nhiều kích cỡ (…-300x200.jpg, ?w=…, /w680/…) → một khoá
const imgKey = (u) => String(u).toLowerCase().replace(/[?#].*$/, '').replace(/-\d{2,4}x\d{2,4}(?=\.\w+$)/, '').replace(/\/w\d{2,4}(_r\d+x\d+)?\//, '/').replace(/^https?:\/\/[^/]+/, '');
const MIN_W = 500;

const out = [];
for (const a of chosen) {
  const html = Date.now() - started < DEADLINE ? await fetchPage(a.link) : '';
  const ld = html ? ldJson(html, a.link) : { images: [], body: '' };
  let body = html ? pageText(html) : '';
  if (body.length < 400 && ld.body.length > body.length) body = ld.body.slice(0, 6000);
  const cands = [];
  const seenImg = new Set();
  for (const u of [...a.images, ...(html ? pageImages(html, a.link) : []), ...ld.images]) {
    const k = imgKey(u);
    if (!u || seenImg.has(k)) continue;
    seenImg.add(k);
    cands.push(u);
  }
  const imgs = [];
  const sizes = new Set();
  for (const u of cands.slice(0, 14)) {
    if (imgs.length >= MAX_IMAGES || Date.now() - started > DEADLINE) break;
    const variants = [u.replace(/-\d{2,4}x\d{2,4}(\.(?:jpe?g|png|webp))(\?.*)?$/i, '$1$2'), u].filter((v, i, s) => s.indexOf(v) === i);
    let d = null;
    for (const v of variants) { d = await download(v, a.link); if (d) break; }
    if (!d || d.w < MIN_W || d.w / d.h > 3.2 || d.h / d.w > 3.2) continue; // bỏ ảnh nhỏ, banner dài
    const sig = d.w + 'x' + d.h + ':' + Math.round(d.buf.length / 2000);
    if (sizes.has(sig)) continue;
    sizes.add(sig);
    imgs.push(d);
  }
  const binary = {};
  for (let k = 0; k < imgs.length; k++) {
    const ext = imgs[k].mime === 'image/png' ? 'png' : imgs[k].mime === 'image/webp' ? 'webp' : 'jpg';
    binary['img' + k] = await this.helpers.prepareBinaryData(imgs[k].buf, 'img' + k + '.' + ext, imgs[k].mime);
  }
  out.push({
    json: {
      topic: a.topic, label: a.label, guide: a.guide, colors: a.colors, lang: a.lang,
      title: a.title, link: a.link, source: a.source, pubDate: new Date(a.date).toISOString(),
      summary: a.summary, body, seenKey: normKey(a.link),
      imageCount: imgs.length, imageSizes: imgs.map((x) => x.w + 'x' + x.h),
    },
    binary: imgs.length ? binary : undefined,
  });
}
if (feedErrors.length) console.log('Feeds lỗi (' + feedErrors.length + '): ' + feedErrors.join(' ; '));
console.log('Chọn ' + out.length + ' bài; số ảnh: ' + out.map((o) => o.json.imageCount).join(', '));
return out;

// Gemini viết câu chuyện cho bài TikTok dạng ảnh trượt: mỗi slide 1 đoạn kể chuyện (vuốt để xem tiếp),
// bằng 2 ngôn ngữ (Anh + Việt), kèm caption + hashtag và tên quốc gia nơi xảy ra tin.
const cfg = $('Config').first().json;
const API_KEY = String(cfg.geminiApiKey || '').trim();
if (!API_KEY || /PASTE|YOUR_/i.test(API_KEY)) throw new Error('Chưa có Gemini API key: điền vào node "Config" (geminiApiKey).');
const BASE = String(cfg.geminiBaseUrl || 'https://generativelanguage.googleapis.com').replace(/\/+$/, '');
const csv = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Gọi generateContent, tự thử lần lượt các model; tự chờ khi bị 429 tạm thời; báo "quotaZero" khi gói free không có hạn mức.
const callGemini = async (models, buildBody, opts = {}) => {
  const started = Date.now();
  const deadline = opts.deadlineMs || 200000;
  let lastErr = null;
  let allQuotaZero = true;
  for (const model of models) {
    for (let attempt = 0; attempt < 3; attempt++) {
      if (Date.now() - started > deadline) break;
      let res;
      try {
        res = await this.helpers.httpRequest({
          method: 'POST',
          url: BASE + '/v1beta/models/' + encodeURIComponent(model) + ':generateContent',
          headers: { 'x-goog-api-key': API_KEY, 'Content-Type': 'application/json' },
          body: buildBody(model), json: true, timeout: opts.timeout || 90000,
          ignoreHttpStatusErrors: true, returnFullResponse: true,
        });
      } catch (e) {
        lastErr = new Error(model + ': ' + e.message);
        allQuotaZero = false;
        await sleep(3000);
        continue;
      }
      const status = res.statusCode;
      const data = res.body;
      if (status >= 200 && status < 300) return { model, data };
      const msg = String((data && data.error && data.error.message) || JSON.stringify(data) || '').split('\n')[0].slice(0, 220);
      const full = String((data && data.error && data.error.message) || '');
      lastErr = new Error(model + ' → HTTP ' + status + ': ' + msg);
      if (status === 401 || status === 403 || (status === 400 && /API key/i.test(msg))) { lastErr.fatal = true; throw lastErr; }
      if (status === 429) {
        if (/limit:\s*0\b/.test(full)) break; // gói hiện tại không có hạn mức cho model này → thử model khác
        allQuotaZero = false;
        const det = ((data.error && data.error.details) || []).find((d) => d.retryDelay);
        const wait = det ? parseFloat(det.retryDelay) : 12;
        if (wait > 90) break; // hết hạn mức theo ngày → model khác
        await sleep((wait + 1) * 1000);
        continue;
      }
      allQuotaZero = false;
      if (status >= 500) { await sleep(4000 * (attempt + 1)); continue; }
      break; // 400 / 404 → model khác
    }
  }
  const err = lastErr || new Error('Gemini request failed');
  if (allQuotaZero) err.quotaZero = true;
  throw err;
};


const extractJson = (text) => {
  const t = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(t); } catch (e) { /* try to find an object inside */ }
  const m = t.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) { /* fallthrough */ } }
  throw new Error('Gemini không trả về JSON hợp lệ: ' + t.slice(0, 120));
};

const TEXT_MODELS = csv(cfg.textModels);
const SLIDES_MIN = Number(cfg.slidesMin || 4), SLIDES_MAX = Number(cfg.slidesMax || 6);
let sd = null;
try { sd = $getWorkflowStaticData('global'); } catch (e) { /* static data unavailable */ }
let stamp;
try { stamp = $now.toFormat('yyyy-LL-dd_HHmm'); } catch (e) { stamp = new Date().toISOString().slice(0, 16).replace('T', '_').replace(':', ''); }
const slug = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/gi, 'd').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50) || 'post';
const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();

const SYSTEM = [
  'You are the editor of a TikTok account about veganism, animal rights and compassion for animals.',
  'You turn one news article into a TikTok PHOTO CAROUSEL that tells the story slide by slide, so viewers keep swiping.',
  'Rules: use ONLY facts from the article; never invent numbers, names or quotes. Never describe gore or graphic suffering.',
  'Warm, compassionate, hopeful; never preachy, never shaming people. Write Vietnamese naturally with correct diacritics (not word-for-word translation).',
].join('\n');

// đã đủ maxArticles bài đạt ở các vòng trước → bỏ qua, bài này để dành cho lần chạy sau (không đánh dấu đã làm)
let accepted = 0;
for (let r = 0; r < $runIndex; r++) {
