const TARGET = Number(cfg.maxArticles || 4);
if (accepted >= TARGET) return $input.all().map((it) => ({ json: { ...it.json, body: undefined, error: 'để dành: đã đủ ' + TARGET + ' bài hôm nay' } }));

const out = [];
const items = $input.all();
for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const j = item.json;
  const N = Math.max(SLIDES_MIN, Math.min(SLIDES_MAX, j.imageCount || SLIDES_MIN));
  try {
    const prompt = [
      'TOPIC: ' + j.label,
      'STYLE GUIDE: ' + j.guide,
      'SOURCE: ' + j.source + ' (article language: ' + (j.lang === 'vi' ? 'Vietnamese' : 'English') + ')',
      'TITLE: ' + j.title,
      'PUBLISHED: ' + j.pubDate,
      'ARTICLE:',
      (j.body && j.body.length > 300 ? j.body : j.summary) || '(no text - rely on the title only and stay general)',
      '',
      'Return ONE JSON object with exactly these keys:',
      '"relevance": integer 0-10 — how well this story fits an account about VEGANISM and ANIMAL RIGHTS. '
        + '9-10: the story is directly about vegan / plant-based eating, animal cruelty or welfare, factory farming, slaughter, fur, animal testing, animal-rights laws or campaigns, wildlife trafficking / poaching, or rescuing, releasing or sheltering animals. '
        + '6-8: animals or plant-based food appear but the main point is something else (business, tourism, general science). '
        + '0-5: animals are only a theme or decoration — art, sculptures, toys, robots, entertainment, nature trivia, animal attacks, pet products, hunting stories, unrelated news. Be strict.',
      '"relevance_reason": one short English sentence explaining the score.',
      '"country_en": ONLY if the news is about a concrete event in one specific country (a rescue, a law, a study, a farm, a city...), the short English name of that country (e.g. "USA", "UK", "Vietnam", "Kenya"). For general topics, tips, recipes or global issues return "". Do not guess from where the publisher is based.',
      '"country_vi": the same country name in Vietnamese (e.g. "Mỹ", "Anh", "Việt Nam", "Kenya"); "" if global or unclear.',
      '"flag": the flag emoji of that country, or "" if none.',
      '"slides_en": array of EXACTLY ' + N + ' strings in English telling the story in order, one per photo. '
        + 'Slide 1 = a strong curiosity hook, 8-14 words. Middle slides = the story step by step, 18-35 words each, each ending with a small cliffhanger or open question that makes people swipe. '
        + 'Last slide = what it means / what we can do, plus a gentle call to follow or comment (do NOT say swipe on the last slide), max 30 words. No hashtags, no emojis, no URLs.',
      '"slides_vi": the same ' + N + ' slides written in natural Vietnamese (same rules).',
      '"caption_en": TikTok caption in English: 1-2 short sentences (max 35 words) that state the ONE main point of this news, using concrete facts from the article (who, what, where, numbers if given). '
        + 'Stay on that single topic. NO questions, NO question marks, NO call to action, no emojis, no hashtags. Do NOT start with the country name (it is added automatically).',
      '"caption_vi": the same caption in natural Vietnamese (same rules: no questions, no question marks).',
      '"hashtags_en": array of 4-6 English hashtags WITHOUT #, no spaces.',
      '"hashtags_vi": array of 4-6 hashtags for Vietnamese viewers WITHOUT #, no spaces, no diacritics (e.g. "anchay", "bảo vệ động vật" → "baovedongvat").',
