    const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
    const r = extractJson(parts.filter((p) => p.text && !p.thought).map((p) => p.text).join(''));
    const MIN_REL = Number(cfg.minRelevance || 7);
    if (!(Number(r.relevance) >= MIN_REL)) {
      if (sd) { sd.seenTikTok = sd.seenTikTok || {}; sd.seenTikTok[j.seenKey] = Date.now(); } // không lấy lại bài này
