    }
    const fix = (arr) => (Array.isArray(arr) ? arr.map(clean).filter(Boolean) : []);
    const tags = (arr) => (Array.isArray(arr) ? arr : String(arr || '').split(/[\s,]+/))
      .map((h) => String(h).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D').replace(/^#+/, '').replace(/[^A-Za-z0-9_]/g, ''))
      .filter(Boolean).slice(0, 6);
    const slidesEn = fix(r.slides_en), slidesVi = fix(r.slides_vi);
    if (slidesEn.length < 2 || slidesVi.length < 2) throw new Error('Gemini thiếu slides');
    const noQ = (s) => clean(s).replace(/[^.!?]*\?\s*/g, '').trim() || clean(s).replace(/\?/g, '.'); // phòng khi Gemini vẫn đặt câu hỏi
    const base = stamp + '_' + slug(j.title);
    const flag = clean(r.flag), cEn = clean(r.country_en), cVi = clean(r.country_vi);
    // caption đăng TikTok (cũng là caption.txt): "🇻🇳 Việt Nam: …" + hashtag + nguồn
    const captionText = (vi, caption, hashtags) => {
      const country = vi ? cVi : cEn;
      const head = country ? (flag ? flag + ' ' : '') + country + ': ' : '';
      return [head + caption, hashtags.map((h) => '#' + h).join(' '), (vi ? 'Nguồn: ' : 'Source: ') + j.source /* link trong caption TikTok không bấm được → chỉ ghi tên nguồn */].filter(Boolean).join('\n\n');
    };
    const capEn = noQ(r.caption_en), capVi = noQ(r.caption_vi), tagsEn = tags(r.hashtags_en), tagsVi = tags(r.hashtags_vi);
    out.push({
      json: {
        ...j, body: undefined, textModel: model,
        countryEn: cEn, countryVi: cVi, flag,
        posts: [
