        ],
      },
      binary: item.binary,
    });
  } catch (e) {
    if (e.fatal) throw new Error('Gemini từ chối API key: ' + e.message);
    out.push({ json: { ...j, body: undefined, error: 'gemini: ' + e.message } });
  }
}
return out;

