const wrap = (text, maxChars) => {
  const lines = [];
  let cur = '';
  for (const w of String(text).split(/\s+/)) {
    if (cur && (cur + ' ' + w).length > maxChars) { lines.push(cur); cur = w; } else cur = cur ? cur + ' ' + w : w;
  }
  if (cur) lines.push(cur);
  const n = lines.length;
  if (n >= 2 && !/\s/.test(lines[n - 1])) {
    const prev = lines[n - 2].split(' ');
    if (prev.length >= 3) { lines[n - 1] = prev.pop() + ' ' + lines[n - 1]; lines[n - 2] = prev.join(' '); }
  }
  return lines;
};
const tidy = (s) => String(s || '').replace(/"([^"]*)"/g, '“$1”').replace(/"/g, '”').replace(/'/g, '’').replace(/\\/g, '/');

const W = 1080, H = 1920, ML = 72, TEXT_W = W - ML - 170, BOTTOM = 1380, FG_Y = 250, MAX_LINES = 11;
const layout = (s) => {
  const { text, first, lang, img, label, footer, idx, total, reuse } = s;
  const vi = lang === 'vi';
  // ảnh ngang → kiểu "card" (ảnh đầy đủ + nền mờ); ảnh dọc / không có ảnh → phủ kín khung
  const fgH = img ? Math.round((W * img.h) / img.w) : 0;
  const card = !!img && fgH <= 860 && !reuse; // ảnh dùng lại lần 2+ → phủ kín khung, cắt vào chỗ khác cho đỡ trùng
  const sc = img ? Math.max(W / img.w, H / img.h) : 1;
  const sw = img ? Math.max(W, Math.round(img.w * sc)) : W, sh = img ? Math.max(H, Math.round(img.h * sc)) : H;
  const fx = [0.5, 0.2, 0.8][reuse % 3], fy = [0.4, 0.5, 0.45][reuse % 3]; // ảnh dùng lại → cắt chỗ khác
  const labelFs = 34, labelH = 62;
  let fs = first ? 76 : 56;
  const minFs = first ? 50 : 40, maxLines = first ? 6 : MAX_LINES;
  const lh = (f) => Math.round(f * (vi ? 1.3 : 1.22));
  const top0 = card ? FG_Y + fgH + 60 + (first ? labelH + 28 : 0) : 0;
  let lines;
  for (;;) {
    lines = wrap(text, Math.floor(TEXT_W / (fs * 0.56)));
    const blockH = lines.length * lh(fs);
    const fits = lines.length <= maxLines && (card ? top0 + blockH <= BOTTOM : blockH <= BOTTOM - 420);
    if (fits || fs <= minFs) break;
    fs -= 2;
  }
  lines = lines.slice(0, MAX_LINES);
  const blockH = lines.length * lh(fs);
  const headTop = card ? Math.min(top0, BOTTOM - blockH) : BOTTOM - blockH;
  const labelY = headTop - 28 - labelH;
  const textTop = first ? labelY : headTop;
  const shadeFrom = Math.max(0, textTop - 340), shadeTo = Math.max(1, textTop - 30);
  const labelText = tidy(label).toUpperCase();
  const counter = idx + 1 + '/' + total;
  return {
    resizeW: W, resizeH: H, cropX: Math.floor((sw - W) * fx), cropY: Math.floor((sh - H) * fy),
    blurW: card ? 54 : W, blurH: card ? 96 : H, // thu nhỏ rồi phóng lại = làm mờ nền (chỉ kiểu card)
    fgW: W, fgH: card ? fgH : 10, fgY: card ? FG_Y : 5000,
    card,
    shadeKey: card ? 'card' : 'fill:' + Math.round(shadeFrom / 20),
    shadeFrom, shadeTo,
    brand: { text: BRAND, x: ML, y: 150 + Math.round(0.74 * 32), fs: 32 },
    counter: { text: counter, x: W - ML - Math.round(counter.length * 0.62 * 32), y: 150 + Math.round(0.74 * 32), fs: 32 },
    label: first
      ? { x: ML, y: labelY, w: Math.round(labelText.length * labelFs * 0.68 + 44), h: labelH, text: labelText, tx: ML + 22, ty: labelY + Math.round((labelH + 0.72 * labelFs) / 2), fs: labelFs }
      : { x: ML, y: 5000, w: 10, h: 10, text: '.', tx: ML, ty: 5000, fs: labelFs },
    lines: Array.from({ length: MAX_LINES }, (_, i) => lines[i]
      ? { text: tidy(lines[i]), y: headTop + i * lh(fs) + Math.round(0.74 * fs), fs, color: first && lines.length >= 2 && i === lines.length - 1 ? '#FFD84D' : '#FFFFFF' }
      : { text: '.', y: 5000, fs, color: '#FFFFFF' }),
    footer: footer
      ? { text: tidy(footer), y: BOTTOM + 40 + Math.round(0.74 * 34), fs: 34 }
      : { text: '.', y: 5000, fs: 34 },
  };
};
const shadeFor = (L) => shadePng(W, H, L.card
  ? () => 135 // nền mờ: tối đều để chữ trắng dễ đọc
  : (y) => Math.max(y < 380 ? 150 * ease(1 - y / 380) : 0, y <= L.shadeFrom ? 0 : y >= L.shadeTo ? 215 : 215 * ease((y - L.shadeFrom) / (L.shadeTo - L.shadeFrom))));

// ---- ảnh của bài ----
const imgs = [];
for (let k = 0; src.binary && src.binary['img' + k]; k++) {
  const [w, h] = String((j.imageSizes || [])[k] || '1200x800').split('x').map(Number); // kích thước đo ở node Fetch
  imgs.push({ key: 'img' + k, bin: src.binary['img' + k], w, h });
}
let gradient = null;
if (!imgs.length) {
  const c = Array.isArray(j.colors) && j.colors.length === 2 ? j.colors : ['#14532d', '#16a34a'];
  gradient = await this.helpers.prepareBinaryData(gradientPng(c[0], c[1]), 'bg.png', 'image/png');
}

const shades = new Map();
const out = [];
for (const p of j.posts) {
  const vi = p.lang === 'vi';
  const country = vi ? j.countryVi : j.countryEn;
  const total = p.slides.length;
  for (let i = 0; i < total; i++) {
    const im = imgs.length ? imgs[i % imgs.length] : null;
    const L = layout({
      text: p.slides[i], first: i === 0, lang: p.lang, idx: i, total,
      img: im, reuse: imgs.length ? Math.floor(i / imgs.length) : 0,
      label: country || (vi ? 'Tin tức' : 'News'),
      footer: i === 0 ? (vi ? 'Vuốt để xem tiếp →' : 'Swipe to see more →') : i === total - 1 ? (vi ? 'Nguồn: ' : 'Source: ') + j.source : '',
    });
    if (!shades.has(L.shadeKey)) shades.set(L.shadeKey, await this.helpers.prepareBinaryData(shadeFor(L), 'shade.png', 'image/png'));
    out.push({
      json: { title: j.title, lang: p.lang, folder: p.folder, slide: i + 1, total, file: String(i + 1).padStart(2, '0') + '.jpg', compose: L },
      binary: { photo: im ? im.bin : gradient, shade: shades.get(L.shadeKey) },
    });
  }
}
return out;

// Mỗi bài → 2 thư mục (bản _en và _vi) trong tiktok_output: 01.jpg, 02.jpg, … + caption.txt (caption đăng TikTok).
const cfg = $('Config').first().json;
const DIR = String(cfg.outputDir || '/files/tiktok_output').replace(/[\\/]+$/, '');
const story = $('Gemini: write story').first().json;

let sd = null;
try { sd = $getWorkflowStaticData('global'); } catch (e) { /* static data unavailable */ }

