    skippedOrFailed: all.filter((x) => x.error).map((x) => (x.title ? x.title + ' — ' : '') + x.error),
  },
}];

// Đưa 2 bài (EN + VI) của bài báo này lên TikTok:
//  1) đẩy ảnh slide lên repo GitHub Pages (TikTok chỉ lấy ảnh từ URL prefix đã xác minh = pagesBaseUrl) — 1 commit,
//     xoá ảnh cũ hơn keepImagesDays;
//  2) tiktokSchedule = true → thêm bài vào queue.json ở trạng thái "pending"; node "Schedule TikTok queue" (chạy sau khi
//     xong mọi bài) chia giờ đều theo số bài thực tế. false → gửi lên TikTok ngay.
// post mode: "inbox" = vào hộp nháp TikTok; "direct" = đăng thẳng (cần app đã được TikTok duyệt).
const cfg = $('Config').first().json;
const story = $('Gemini: write story').first().json;
const items = $input.all();
// ---- dùng chung với node "Schedule TikTok queue" và "Publish due TikTok posts" ----
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const filled = (v) => { const s = String(v || '').trim(); return s && !/PASTE|YOUR_/i.test(s) ? s : ''; };
const GH_TOKEN = filled(cfg.githubToken), REPO = String(cfg.githubRepo || '').trim();
const PAGES = String(cfg.pagesBaseUrl || '').replace(/\/*$/, '/');
const CK = filled(cfg.tiktokClientKey), CS = filled(cfg.tiktokClientSecret), RT = filled(cfg.tiktokRefreshToken);
const MODE = String(cfg.tiktokPostMode || 'inbox').toLowerCase() === 'direct' ? 'DIRECT_POST' : 'MEDIA_UPLOAD';
const missing = [!GH_TOKEN && 'githubToken', !REPO && 'githubRepo', !CK && 'tiktokClientKey', !CS && 'tiktokClientSecret', !RT && 'tiktokRefreshToken'].filter(Boolean);

const http = async (opts) => {
  const res = await this.helpers.httpRequest({ json: true, timeout: 60000, ignoreHttpStatusErrors: true, returnFullResponse: true, ...opts });
  return { status: res.statusCode, body: res.body };
};
const gh = (method, path, body) => http({
  method, url: 'https://api.github.com/repos/' + REPO + path, body,
  headers: { Authorization: 'Bearer ' + GH_TOKEN, Accept: 'application/vnd.github+json', 'User-Agent': 'n8n-vegan-tiktok', 'X-GitHub-Api-Version': '2022-11-28' },
});
const must = (r, what) => { if (r.status >= 300) throw new Error(what + ' → HTTP ' + r.status + ' ' + JSON.stringify(r.body).slice(0, 200)); return r.body; };

// hàng đợi hẹn giờ = file queue.json trong repo (n8n không lưu static data khi chạy tay, nên không dùng static data)
const readQueue = async () => {
  const r = await gh('GET', '/contents/queue.json?ref=main');
  if (r.status === 404) return { queue: [], sha: null };
  const b = must(r, 'GitHub queue.json');
  return { queue: JSON.parse(Buffer.from(b.content, 'base64').toString('utf8') || '[]'), sha: b.sha };
};

const tiktokAccess = async () => {
  const tok = await http({
    method: 'POST', url: 'https://open.tiktokapis.com/v2/oauth/token/', json: false,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'client_key=' + encodeURIComponent(CK) + '&client_secret=' + encodeURIComponent(CS) + '&grant_type=refresh_token&refresh_token=' + encodeURIComponent(RT),
  });
  try { if (typeof tok.body === 'string') tok.body = JSON.parse(tok.body); } catch (e) { /* để nguyên */ }
  if (!tok.body || !tok.body.access_token) throw new Error('TikTok refresh token lỗi: ' + JSON.stringify(tok.body).slice(0, 200) + ' — kết nối lại tài khoản TikTok');
  return tok.body.access_token;
};
// gửi 1 bài ảnh (ảnh đã nằm trên GitHub Pages) → trạng thái dễ đọc
const tiktokPost = async (access, { title, captionText, photos }) => {
  const tt = (path, body) => http({ method: 'POST', url: 'https://open.tiktokapis.com' + path, body, headers: { Authorization: 'Bearer ' + access, 'Content-Type': 'application/json; charset=UTF-8' } });
  const body = {
    media_type: 'PHOTO', post_mode: MODE,
    post_info: MODE === 'DIRECT_POST'
      ? { title: title.slice(0, 90), description: captionText.slice(0, 4000), privacy_level: String(cfg.tiktokPrivacy || 'SELF_ONLY'), disable_comment: false, auto_add_music: true }
      : { title: title.slice(0, 90), description: captionText.slice(0, 4000) },
    source_info: { source: 'PULL_FROM_URL', photo_cover_index: 0, photo_images: photos },
  };
  const init = await tt('/v2/post/publish/content/init/', body);
  const pid = init.body && init.body.data && init.body.data.publish_id;
  if (!pid) return 'error: ' + JSON.stringify((init.body && init.body.error) || init.body).slice(0, 200);
  let st = 'PROCESSING';
  for (let t = 0; t < 8 && /PROCESSING|DOWNLOAD|UPLOAD/.test(st); t++) {
    await sleep(4000);
    const s = await tt('/v2/post/publish/status/fetch/', { publish_id: pid });
    const d = (s.body && s.body.data) || {};
    st = d.status || st;
    if (st === 'FAILED') st = 'error: FAILED ' + (d.fail_reason || '');
  }
  return st === 'SEND_TO_USER_INBOX' ? 'inbox (vào hộp nháp TikTok)' : st === 'PUBLISH_COMPLETE' ? 'published' : st;
};
const SCHEDULE = cfg.tiktokSchedule !== false && String(cfg.tiktokSchedule).toLowerCase() !== 'false';
const KEEP_DAYS = Number(cfg.keepImagesDays || 7);
const results = {}; // folder → trạng thái
const finish = () => items.map((it) => ({ json: { ...it.json, tiktok: results[it.json.folder] || '' }, binary: it.binary }));
if (missing.length) {
  for (const p of story.posts) results[p.folder] = 'skipped (chưa có ' + missing.join(', ') + ' trong Config)';
  return finish();
}
const runId = String($execution.id);

try {
  for (let attempt = 0; attempt < 3; attempt++) {
    const ref = must(await gh('GET', '/git/ref/heads/main'), 'GitHub ref');
    const head = must(await gh('GET', '/git/commits/' + ref.object.sha), 'GitHub commit');
    const entries = [];
    const urls = {}; // folder → [url ảnh theo thứ tự slide]
    for (let i = 0; i < items.length; i++) {
      const s = items[i].json;
      if (!items[i].binary || !items[i].binary.image) continue;
      const buf = await this.helpers.getBinaryDataBuffer(i, 'image');
      const blob = must(await gh('POST', '/git/blobs', { content: buf.toString('base64'), encoding: 'base64' }), 'GitHub blob');
      const path = 'p/' + s.folder + '/' + s.file;
      entries.push({ path, mode: '100644', type: 'blob', sha: blob.sha });
      (urls[s.folder] = urls[s.folder] || [])[s.slide - 1] = PAGES + path;
    }
    // xoá ảnh bài cũ (p/<yyyy-mm-dd>_…) để repo không phình to
    const tree = (await gh('GET', '/git/trees/' + head.tree.sha + '?recursive=1')).body || {};
    const cutoff = new Date(Date.now() - KEEP_DAYS * 86400000).toISOString().slice(0, 10);
    for (const t of tree.tree || []) {
      const m = t.type === 'blob' && t.path.match(/^p\/(\d{4}-\d{2}-\d{2})/);
      if (m && m[1] < cutoff) entries.push({ path: t.path, mode: '100644', type: 'blob', sha: null });
    }
    if (SCHEDULE) {
      let queue = (await readQueue()).queue.filter((q) => !(q.status !== 'queued' && q.status !== 'pending' && Date.now() - (q.due || 0) > KEEP_DAYS * 86400000));
      for (const p of story.posts) {
        const photos = (urls[p.folder] || []).filter(Boolean);
        if (!photos.length) { results[p.folder] = 'error: không có ảnh'; continue; }
        queue = queue.filter((q) => q.folder !== p.folder);
        queue.push({ folder: p.folder, lang: p.lang, runId, order: $runIndex, status: 'pending',
          title: String(p.slides[0] || story.title).slice(0, 90), captionText: p.captionText, photos, attempts: 0 });
        results[p.folder] = 'pending (xếp giờ khi xong lần chạy)';
      }
      const qb = must(await gh('POST', '/git/blobs', { content: Buffer.from(JSON.stringify(queue, null, 1)).toString('base64'), encoding: 'base64' }), 'GitHub queue blob');
      entries.push({ path: 'queue.json', mode: '100644', type: 'blob', sha: qb.sha });
    }
    const newTree = must(await gh('POST', '/git/trees', { base_tree: head.tree.sha, tree: entries }), 'GitHub tree');
    const commit = must(await gh('POST', '/git/commits', { message: 'TikTok slides: ' + story.title.slice(0, 60), tree: newTree.sha, parents: [ref.object.sha] }), 'GitHub new commit');
    const upd = await gh('PATCH', '/git/refs/heads/main', { sha: commit.sha });
    if (upd.status === 422 && attempt < 2) { for (const k of Object.keys(results)) delete results[k]; await sleep(3000); continue; } // repo vừa đổi (node gửi bài ghi queue) → làm lại
    must(upd, 'GitHub update ref');

    if (!SCHEDULE) {
      // gửi ngay: chờ GitHub Pages đăng xong ảnh cuối rồi gọi TikTok
      const last = Object.values(urls).flat().pop();
      let live = false;
      for (let t = 0; t < 24 && !live; t++) {
        await sleep(5000);
        const r = await http({ method: 'GET', url: last + '?v=' + commit.sha.slice(0, 7), json: false, encoding: 'arraybuffer', timeout: 15000 }).catch(() => ({ status: 0 }));
        live = r.status === 200;
      }
      if (!live) throw new Error('GitHub Pages chưa đăng ảnh sau 2 phút: ' + last);
      const access = await tiktokAccess();
      for (const p of story.posts) {
        const photos = (urls[p.folder] || []).filter(Boolean);
        results[p.folder] = photos.length ? await tiktokPost(access, { title: String(p.slides[0] || story.title), captionText: p.captionText, photos }) : 'error: không có ảnh';
      }
    }
    break;
  }
} catch (e) {
  for (const p of story.posts) if (!results[p.folder]) results[p.folder] = 'error: ' + e.message;
}
return finish();

// Chạy mỗi 15 phút: gửi lên TikTok các bài trong queue.json (repo GitHub Pages) đã đến giờ.
// Mỗi ngôn ngữ tối đa 1 bài / lần chạy để bài không dồn cục khi máy vừa thức dậy; lỗi thì thử lại tối đa 3 lần.
const cfg = $('Config').first().json;
// ---- dùng chung với node "Publish to TikTok" ----
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const filled = (v) => { const s = String(v || '').trim(); return s && !/PASTE|YOUR_/i.test(s) ? s : ''; };
const GH_TOKEN = filled(cfg.githubToken), REPO = String(cfg.githubRepo || '').trim();
const PAGES = String(cfg.pagesBaseUrl || '').replace(/\/*$/, '/');
