const MODE = String(cfg.tiktokPostMode || 'inbox').toLowerCase() === 'direct' ? 'DIRECT_POST' : 'MEDIA_UPLOAD';
const missing = [!GH_TOKEN && 'githubToken', !REPO && 'githubRepo', !CK && 'tiktokClientKey', !CS && 'tiktokClientSecret', !RT && 'tiktokRefreshToken'].filter(Boolean);

const http = async (opts) => {
  const res = await this.helpers.httpRequest({ json: true, timeout: 60000, ignoreHttpStatusErrors: true, returnFullResponse: true, ...opts });
  return { status: res.statusCode, body: res.body };
};
const gh = (method, path, body) => http({
