// gửi 1 bài ảnh (ảnh đã nằm trên GitHub Pages) → trạng thái dễ đọc
const tiktokPost = async (access, { title, captionText, photos }) => {
  const tt = (path, body) => http({ method: 'POST', url: 'https://open.tiktokapis.com' + path, body, headers: { Authorization: 'Bearer ' + access, 'Content-Type': 'application/json; charset=UTF-8' } });
  const body = {
    media_type: 'PHOTO', post_mode: MODE,
    post_info: MODE === 'DIRECT_POST'
      ? { title: title.slice(0, 90), description: captionText.slice(0, 4000), privacy_level: String(cfg.tiktokPrivacy || 'SELF_ONLY'), disable_comment: false, auto_add_music: true }
      : { title: title.slice(0, 90), description: captionText.slice(0, 4000) },
    source_info: { source: 'PULL_FROM_URL', photo_cover_index: 0, photo_images: photos },
  };
  const init = await tt('/v2/post/publish/content/init/', body);
  const pid = init.body && init.body.data && init.body.data.publish_id;
  if (!pid) return 'error: ' + JSON.stringify((init.body && init.body.error) || init.body).slice(0, 200);
  let st = 'PROCESSING';
  for (let t = 0; t < 8 && /PROCESSING|DOWNLOAD|UPLOAD/.test(st); t++) {
    await sleep(4000);
    const s = await tt('/v2/post/publish/status/fetch/', { publish_id: pid });
    const d = (s.body && s.body.data) || {};
    st = d.status || st;
    if (st === 'FAILED') st = 'error: FAILED ' + (d.fail_reason || '');
  }
  return st === 'SEND_TO_USER_INBOX' ? 'inbox (vào hộp nháp TikTok)' : st === 'PUBLISH_COMPLETE' ? 'published' : st;
};
if (missing.length) return [{ json: { skipped: 'chưa có ' + missing.join(', ') + ' trong Config' } }];

const sent = [];
for (let attempt = 0; attempt < 3; attempt++) {
  const { queue, sha } = await readQueue();
  const now = Date.now();
  const due = [];
  for (const lang of ['en', 'vi']) {
    const q = queue.find((x) => x.lang === lang && x.status === 'queued' && x.due <= now);
    if (q) due.push(q);
  }
  if (!due.length) return [{ json: { nothingDue: true, queued: queue.filter((x) => x.status === 'queued').map((x) => x.dueLocal + ' — ' + x.folder) } }];
  const access = await tiktokAccess();
  for (const q of due) {
    const st = await tiktokPost(access, q);
    q.attempts = (q.attempts || 0) + 1;
    q.result = st;
    q.sentAt = new Date().toISOString();
    q.status = /^error/.test(st) ? (q.attempts >= 3 ? 'failed' : 'queued') : 'sent';
    if (q.status === 'queued') q.due = now + 30 * 60000; // lỗi → thử lại sau 30 phút
    sent.push(q.folder + ' → ' + st);
  }
  const put = await gh('PUT', '/contents/queue.json', {
    message: 'TikTok queue: sent ' + due.map((q) => q.folder).join(', ').slice(0, 120),
    content: Buffer.from(JSON.stringify(queue, null, 1)).toString('base64'), sha, branch: 'main',
  });
  if (put.status === 409 || put.status === 422) { // queue.json vừa bị node khác ghi → đọc lại, chỉ cập nhật trạng thái các bài vừa gửi
    const fresh = await readQueue();
    for (const q of due) { const f = fresh.queue.find((x) => x.folder === q.folder); if (f) Object.assign(f, { status: q.status, result: q.result, sentAt: q.sentAt, attempts: q.attempts, due: q.due }); }
    must(await gh('PUT', '/contents/queue.json', { message: 'TikTok queue: sent (retry)', content: Buffer.from(JSON.stringify(fresh.queue, null, 1)).toString('base64'), sha: fresh.sha, branch: 'main' }), 'GitHub queue.json');
  } else must(put, 'GitHub queue.json');
  break;
}
return [{ json: { sent } }];

// Chạy 1 lần sau khi xử lý xong mọi bài: chia giờ đăng cho các bài "pending" của lần chạy này trong queue.json.
// Bài EN chia đều tiktokEnStart–tiktokEnEnd (giờ tiktokEnTimezone), bài VI chia đều tiktokViStart–tiktokViEnd (giờ tiktokViTimezone),
