});
const must = (r, what) => { if (r.status >= 300) throw new Error(what + ' → HTTP ' + r.status + ' ' + JSON.stringify(r.body).slice(0, 200)); return r.body; };

// hàng đợi hẹn giờ = file queue.json trong repo (n8n không lưu static data khi chạy tay, nên không dùng static data)
const readQueue = async () => {
  const r = await gh('GET', '/contents/queue.json?ref=main');
  if (r.status === 404) return { queue: [], sha: null };
  const b = must(r, 'GitHub queue.json');
  return { queue: JSON.parse(Buffer.from(b.content, 'base64').toString('utf8') || '[]'), sha: b.sha };
};

const tiktokAccess = async () => {
  const tok = await http({
    method: 'POST', url: 'https://open.tiktokapis.com/v2/oauth/token/', json: false,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'client_key=' + encodeURIComponent(CK) + '&client_secret=' + encodeURIComponent(CS) + '&grant_type=refresh_token&refresh_token=' + encodeURIComponent(RT),
  });
  try { if (typeof tok.body === 'string') tok.body = JSON.parse(tok.body); } catch (e) { /* để nguyên */ }
  if (!tok.body || !tok.body.access_token) throw new Error('TikTok refresh token lỗi: ' + JSON.stringify(tok.body).slice(0, 200) + ' — kết nối lại tài khoản TikTok');
  return tok.body.access_token;
};
// gửi 1 bài ảnh (ảnh đã nằm trên GitHub Pages) → trạng thái dễ đọc
const tiktokPost = async (access, { title, captionText, photos }) => {
  const tt = (path, body) => http({ method: 'POST', url: 'https://open.tiktokapis.com' + path, body, headers: { Authorization: 'Bearer ' + access, 'Content-Type': 'application/json; charset=UTF-8' } });
  const body = {
    media_type: 'PHOTO', post_mode: MODE,
    post_info: MODE === 'DIRECT_POST'
      ? { title: title.slice(0, 90), description: captionText.slice(0, 4000), privacy_level: String(cfg.tiktokPrivacy || 'SELF_ONLY'), disable_comment: false, auto_add_music: true }
      : { title: title.slice(0, 90), description: captionText.slice(0, 4000) },
    source_info: { source: 'PULL_FROM_URL', photo_cover_index: 0, photo_images: photos },
  };
  const init = await tt('/v2/post/publish/content/init/', body);
  const pid = init.body && init.body.data && init.body.data.publish_id;
  if (!pid) return 'error: ' + JSON.stringify((init.body && init.body.error) || init.body).slice(0, 200);
  let st = 'PROCESSING';
  for (let t = 0; t < 8 && /PROCESSING|DOWNLOAD|UPLOAD/.test(st); t++) {
    await sleep(4000);
    const s = await tt('/v2/post/publish/status/fetch/', { publish_id: pid });
    const d = (s.body && s.body.data) || {};
    st = d.status || st;
    if (st === 'FAILED') st = 'error: FAILED ' + (d.fail_reason || '');
  }
  return st === 'SEND_TO_USER_INBOX' ? 'inbox (vào hộp nháp TikTok)' : st === 'PUBLISH_COMPLETE' ? 'published' : st;
};
const SCHEDULE = cfg.tiktokSchedule !== false && String(cfg.tiktokSchedule).toLowerCase() !== 'false';
if (missing.length || !SCHEDULE) return items;
const runId = String($execution.id);
const hm = (s, d) => { const m = String(s || d).match(/^(\d{1,2}):(\d{2})$/); return m ? { hour: +m[1], minute: +m[2] } : hm(d, d); };
const WIN = {
  en: { tz: cfg.tiktokEnTimezone || 'America/New_York', start: hm(cfg.tiktokEnStart, '08:00'), end: hm(cfg.tiktokEnEnd, '20:00') },
  vi: { tz: cfg.tiktokViTimezone || 'Asia/Ho_Chi_Minh', start: hm(cfg.tiktokViStart, '10:00'), end: hm(cfg.tiktokViEnd, '22:00') },
};
const label = {}; // folder → "scheduled …"
for (let attempt = 0; attempt < 3; attempt++) {
  const { queue, sha } = await readQueue();
  const mine = queue.filter((q) => q.runId === runId && q.status === 'pending');
  if (!mine.length) return items;
  for (const lang of Object.keys(WIN)) {
    const list = mine.filter((q) => q.lang === lang).sort((a, b) => a.order - b.order);
    if (!list.length) continue;
    const w = WIN[lang];
    const now = DateTime.now().setZone(w.tz);
    let day = now.startOf('day');
    if (day.set(w.start) < now.plus({ minutes: 20 })) day = day.plus({ days: 1 });
    const taken = (d) => queue.some((q) => q.lang === lang && q.runId !== runId && q.day === d.toISODate());
    for (let k = 0; k < 14 && taken(day); k++) day = day.plus({ days: 1 });
    const start = day.set(w.start);
    let end = day.set(w.end);
    if (end <= start) end = end.plus({ days: 1 });
    const step = list.length > 1 ? (end - start) / (list.length - 1) : 0;
    list.forEach((q, i) => {
      const when = start.plus({ milliseconds: Math.round(step * i) }).startOf('minute');
      Object.assign(q, { status: 'queued', day: day.toISODate(), due: when.toMillis(), dueLocal: when.toFormat('yyyy-LL-dd HH:mm ZZZZ') });
      label[q.folder] = 'scheduled ' + when.toFormat('dd/LL HH:mm ZZZZ') + ' (giờ VN ' + when.setZone('Asia/Ho_Chi_Minh').toFormat('dd/LL HH:mm') + ')';
    });
  }
  queue.sort((a, b) => (a.due || 0) - (b.due || 0));
  const put = await gh('PUT', '/contents/queue.json', { message: 'TikTok queue: xếp giờ ' + mine.length + ' bài', content: Buffer.from(JSON.stringify(queue, null, 1)).toString('base64'), sha, branch: 'main' });
  if ((put.status === 409 || put.status === 422) && attempt < 2) { await sleep(3000); continue; } // queue vừa bị ghi → đọc lại
  must(put, 'GitHub queue.json');
  break;
}
return items.map((it) => ({ json: { ...it.json, tiktok: label[it.json.folder] || it.json.tiktok }, binary: it.binary }));
